#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    Cat(string n) : name(n) {
        cout << name << " 初始化啦" << endl;
    }
    ~Cat() {
        cout << name << " 走啦" << endl;
    }
};

void kitchen() {
    Cat tmp("胖虎");
    cout << tmp.name << " 处理完成了" << endl;
}

int main() {
    Cat a("张三");
    kitchen();
    Cat b("李四");
    cout << "处理结束" << endl;
    return 0;
}

